package com.example.solarfarm.controller;
import com.example.solarfarm.common.Dtos; import com.example.solarfarm.repository.FaultEventRepository; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/fault-events") public class FaultEventController { private final FaultEventRepository repo; public FaultEventController(FaultEventRepository r){repo=r;} @GetMapping public List<Dtos.FaultEventResponse> all(){return repo.findAll().stream().map(this::map).toList();} @GetMapping("/panel/{panelId}") public List<Dtos.FaultEventResponse> panel(@PathVariable String panelId){return repo.findByPanel_PanelIdOrderByStartTimeDesc(panelId).stream().map(this::map).toList();} private Dtos.FaultEventResponse map(com.example.solarfarm.domain.FaultEvent e){return new Dtos.FaultEventResponse(e.getEventId(),e.getPanel().getPanelId(),e.getStartTime(),e.getEndTime(),e.getFaultType(),e.getSeverity(),e.getStatus().name());} }
